var n=`1287-funchi`;var t=`world-1287`;var o=`CW`;var r=`central-america-caribbean`;var a=4;var s=53;var u={en:`Funchi`,ua:`Фунчі`};var d={en:`Funchi is a dish from Aruba and Curaçao featuring cornmeal, queso fresco. This home-sized recipe records each ingredient at the step where it is used.`,ua:`Фунчі, страва кухні країни Аруба й Кюрасао з такими основними складниками: кукурудзяна крупа дрібного помелу, кесо фреско. У домашньому рецепті кожний продукт прив’язаний до етапу його використання.`};var l=[{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:9,i:[[`cornmeal`,400,`g`],[`water`,920,`ml`],[`unsalted-butter`,45,`g`]]},{en:`Combine the remaining ingredients, cover partly and stew gently for about 18 minutes until the flavors meld and everything is tender.`,ua:`З’єднайте решту складників, частково накрийте й тушкуйте приблизно 18 хвилин до поєднання смаків і м’якості продуктів.`,t:[`stewing`],m:18,i:[]},{en:`Shape, press or roll the prepared dough or mixture into portions appropriate to this dish.`,ua:`Розпластайте, розкачайте або сформуйте з підготовленого тіста чи маси порції потрібної форми.`,t:[`pressing`,`rolling-out-dough`],m:11,i:[]},{en:`Heat the pan over medium heat, shape or spoon out portions, and fry for about 12 minutes total until golden on both sides and fully cooked.`,ua:`Розігрійте сковороду на середньому вогні, сформуйте або викладіть порції ложкою й смажте загалом приблизно 12 хвилин до золотистості з обох боків і повної готовності.`,t:[`pan-frying`],m:12,i:[[`canola-oil`,75,`ml`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`queso-fresco`,90,`g`]]}];var h={slug:n,id:t,country:`CW`,region:r,servings:4,minutes:53,title:u,text:d,steps:l};export{o as country,h as default,t as id,s as minutes,r as region,a as servings,n as slug,l as steps,d as text,u as title};